  "implementation": "def solve(case):
    import collections
    nodes = case.get('nodes')
    if not isinstance(nodes, list):
        raise ValueError('missing nodes')
    required = set(case.get('required_symbols', []))
    node_map = {n['id']: n for n in nodes}
    children = {}
    for n in nodes:
        p = n.get('parent')
        if p is not None:
            children.setdefault(p, []).append(n['id'])
    roots = [nid for nid, n in node_map.items() if n.get('parent') is None]
    if len(roots) != 1:
        raise ValueError('unique root required')
    root_id = roots[0]
    symbols = collections.Counter(n['symbol'] for n in nodes)
    for sym in required:
        if sym not in symbols:
            raise ValueError(f'required symbol {sym} missing')
    retained = set(node_map.keys())
    order = sorted(node_map.items(), key=lambda kv: (-kv[1]['depth'], kv[0]))
    removed = []
    for nid, node in order:
        if not node.get('removable', False):
            continue
        if nid == root_id:
            continue
        if any(c in retained for c in children.get(nid, [])):
            continue
        sym = node['symbol']
        if sym in required and symbols[sym] == 1:
            continue
        removed.append(nid)
        retained.discard(nid)
        symbols[sym] -= 1
    retained_sorted = sorted(retained)
    return {'removed_node_ids': removed, 'retained_node_ids': retained_sorted}"
}
